import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract_packages(data):
    result = {}
    for proj in data.get('projects', []):
        path = proj['path']
        name = path.split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            tf = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], tf)
                pkgs[key] = pkg['resolvedVersion']
        result[name] = pkgs
    return result

b = extract_packages(baseline)
a = extract_packages(after)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes.append((proj, key[0], key[1], bv, av))

if changes:
    print('CHANGES DETECTED:')
    for c in changes:
        print(f'  {c[0]}: {c[1]} ({c[2]}): {c[3]} -> {c[4]}')
else:
    print('NO CHANGES - all packages resolve identically')
"

